import{_ as t,o as r,c as s,a0 as a}from"./chunks/framework.D4fUSYzX.js";const u=JSON.parse(`{"title":"ADR 0074: The rework prompt carries the pull request's review verdict","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0074-the-rework-prompt-carries-the-pull-requests-review-verdict.md","filePath":"adr/0074-the-rework-prompt-carries-the-pull-requests-review-verdict.md"}`),o={name:"adr/0074-the-rework-prompt-carries-the-pull-requests-review-verdict.md"};function n(i,e,h,d,l,c){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0074-the-rework-prompt-carries-the-pull-request-s-review-verdict" tabindex="-1">ADR 0074: The rework prompt carries the pull request&#39;s review verdict <a class="header-anchor" href="#adr-0074-the-rework-prompt-carries-the-pull-request-s-review-verdict" aria-label="Permalink to &quot;ADR 0074: The rework prompt carries the pull request&#39;s review verdict&quot;">​</a></h1><p>Status: accepted Date: 2026-10-01</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The <code>needs-work</code> state offers the rework task type on a pull request ticket. The shipped rework template told the agent to &quot;read last review comments&quot; itself, so the agent hunted the review&#39;s feedback across the pull request&#39;s own timelines.</p><p>The plane already knows where the feedback lives. At the settle, the score judgment reads both posting timelines - the pull request&#39;s issue comments and its review bodies - and takes the newest record that carries the template&#39;s fixed score line (ADR 0047, ADR 0053, ADR 0057, ADR 0063). That record, the review verdict, is exactly the input the rework agent needs, and the plane read it one settle earlier for the judgment. The handoff, by contrast, rendered only the ticket&#39;s projected facts: title, description, labels, source facts. The verdict never stands in the projection, so the rework agent started blind and spent its own turn on the read.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><strong>The rework prompt carries the review verdict.</strong> A new known placeholder, <code>{review-verdict}</code>, joins the prompt placeholders. When a task type&#39;s template references it, the handoff reads the verdict live from the source at the prompt render: the same two timelines, the same newest-score-carrying-record rule, and the same per-timeline fail-open the score judgment uses. The read is gated on the template&#39;s reference to the placeholder, the way the judgment gates its two timelines on its score branch: a template that does not reference the placeholder issues no read.</p><p><strong>The fill is the verdict&#39;s body under a one-line header that names the posting timeline and the post&#39;s time.</strong></p><p><strong>The read degrades to a fact line and never blocks the handoff.</strong> When no record carries the fixed score line, the fill is <code>No review verdict found on the pull request.</code>. When every timeline&#39;s read fails, the fill is <code>The review verdict read failed: &lt;reason&gt;.</code>. The handoff goes ahead either way, and the template keeps the fallback instruction: when the section carries no verdict, the agent reads the pull request&#39;s comments itself. The plane&#39;s fill states the fact, and the template states the instruction.</p><p><strong>The shipped rework template moves with the placeholder.</strong> The &quot;Read Comments&quot; step dies, a <code>### Review verdict</code> section leads the prompt, and the first instruction corrects the code according to the verdict above and carries the fallback. The template change reaches existing installs by the operator&#39;s hand only, the policy under which the review template&#39;s outcome line moved (ADR 0053): an install that keeps its old template loses the injection and gains nothing, because a template that references no placeholder issues no read and renders no section.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The rework agent starts with the review&#39;s feedback in its prompt: it does not spend its turn hunting the timelines, and it cannot settle on a wrong or stale post. The judgment&#39;s record is its input, so the rework corrects what the judgment measured.</li><li>A pull request a human labels <code>needs-work</code> by hand, with no verdict post, stays handable: the fill is the fact line, the template&#39;s fallback instruction runs, and the agent reads the timelines itself.</li><li>The handoff issues at most two source reads, and only when the template asks for them. A handoff whose template references no placeholder is unchanged in its command stream.</li><li>The verdict read now stands at two points, the settle&#39;s judgment and the handoff&#39;s prompt. The rule is one and the read is live at both, so the two points never decide on different records for the same posts.</li><li>A restart of a rework handoff re-renders the prompt and re-reads the verdict, the way the first handoff does: a new agent session starts with the same context.</li><li>The placeholder joins the config check&#39;s known list and the configuration docs&#39; placeholder table. Any other brace pair in a template stays a startup error.</li></ul>',12)])])}const m=t(o,[["render",n]]);export{u as __pageData,m as default};
